apparmor./etc/apparmor.d/usr.bin.useradd:
#include <tunables/global>

/usr/bin/useradd {

  #include <abstractions/base>
  #include <abstractions/nameservice>

  /etc/passwd rw,
  /etc/shadow rw,
  /etc/group rw,
  /etc/gshadow rw,
  /etc/login.defs r,
  /etc/default/** r,
  /etc/skel/** r,
  /home/** rw,
  /var/spool/mail/** rw,

  deny /etc/sudoers r,
  deny /etc/ssh/** r,
}

apparmor./etc/apparmor.d/usr.bin.curl:
#include <tunables/global>

/usr/bin/curl {

  #include <abstractions/base>
  #include <abstractions/nameservice>
  #include <abstractions/openssl>
  #include <abstractions/ssl_certs>
  #include <abstractions/user-download>
  #include <abstractions/user-tmp>

  network inet stream,
  network inet6 stream,
  network unix stream,

  /etc/ssl/** r,
  /etc/ca-certificates/** r,
  /etc/resolv.conf r,
  /etc/hosts r,
  /dev/null rw,
  /dev/urandom r,
  /tmp/** rwkl,
  /var/tmp/** rwkl,
  /home/** rwkl,
  /root/** rwkl,
  /var/cache/** rwkl,
  owner @{HOME}/** rwkl,

  deny /etc/shadow r,
  deny /etc/gshadow r,
  deny /etc/sudoers r,
  deny /etc/ssh/sshd_config r,
  deny /etc/ssh/*key* r,
}

